import { describe, it, expect } from 'vitest'
import { themePresets, themeCategories } from './themePresets'

/**
 * `themePresets` is an autogenerated palette table consumed by
 * `ThemeProvider.applyThemeCSS`. Two consumer contracts depend on its shape:
 *
 *  1. It is collapsed into a keyed lookup via
 *     `Object.fromEntries(themePresets.map(p => [p.id, p]))`, so a duplicate
 *     `id` would silently drop a whole theme.
 *  2. The display-mode picker groups presets by `category` against
 *     `['Core', ...themeCategories]`, so a category that is used but not
 *     declared (or declared but unused) leaves an orphaned / empty group.
 *
 * The palette values are also injected verbatim as CSS custom properties
 * (`--bg`, `--text-primary`, …) and `color-scheme`, so a malformed colour or a
 * light/dark scheme paired with unreadable text ships a visibly broken theme.
 *
 * These tests lock those invariants so a future regeneration is caught here
 * instead of in production.
 */

/** Solid 6-digit hex — the form every surface/text colour must take. */
const HEX = /^#[0-9a-fA-F]{6}$/
/** `rgba(r, g, b, a)` with a 0–1 alpha — the form the glass layers must take. */
const RGBA = /^rgba\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*(?:0|1|0?\.\d+)\s*\)$/

const HEX_FIELDS = ['bg', 'surface1', 'surface2', 'surface3', 'textPrimary', 'textSecondary', 'textMuted'] as const
const RGBA_FIELDS = ['glassBg', 'glassBorder'] as const
const REQUIRED_FIELDS = [
  'id', 'name', 'category', 'colorScheme',
  'bg', 'surface1', 'surface2', 'surface3',
  'glassBg', 'glassBorder',
  'textPrimary', 'textSecondary', 'textMuted',
] as const

/** WCAG sRGB relative-luminance approximation (0 = black … 1 = white). */
function luminance(hex: string): number {
  const r = parseInt(hex.slice(1, 3), 16)
  const g = parseInt(hex.slice(3, 5), 16)
  const b = parseInt(hex.slice(5, 7), 16)
  return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255
}

describe('themePresets — module shape', () => {
  it('exposes non-empty preset and category collections', () => {
    expect(Array.isArray(themePresets)).toBe(true)
    expect(Array.isArray(themeCategories)).toBe(true)
    expect(themePresets.length).toBeGreaterThan(0)
    expect(themeCategories.length).toBeGreaterThan(0)
  })

  it('gives every preset all fields ThemeProvider reads', () => {
    const offenders: string[] = []
    for (const preset of themePresets) {
      for (const field of REQUIRED_FIELDS) {
        const value = preset[field]
        if (value === undefined || value === '') {
          offenders.push(`${preset.id ?? '<no-id>'}.${field}`)
        }
      }
    }
    expect(offenders).toEqual([])
  })
})

describe('themePresets — id lookup contract', () => {
  it('keeps every preset id unique', () => {
    const ids = themePresets.map((p) => p.id)
    const duplicates = ids.filter((id, i) => ids.indexOf(id) !== i)
    expect(duplicates).toEqual([])
    expect(new Set(ids).size).toBe(ids.length)
  })

  it('loses no preset when collapsed into the ThemeProvider lookup', () => {
    // Mirrors `Object.fromEntries(themePresets.map(p => [p.id, p]))`.
    const lookup = Object.fromEntries(themePresets.map((p) => [p.id, p]))
    expect(Object.keys(lookup).length).toBe(themePresets.length)
    const first = themePresets[0]
    expect(lookup[first.id]).toEqual(first)
  })

  it('uses lowercase kebab-case ids with no stray whitespace', () => {
    const kebab = /^[a-z0-9]+(?:-[a-z0-9]+)*$/
    const offenders = themePresets
      .map((p) => p.id)
      .filter((id) => !kebab.test(id) || id !== id.trim())
    expect(offenders).toEqual([])
  })

  it('gives every preset a unique, trimmed, non-empty name', () => {
    const names = themePresets.map((p) => p.name)
    expect(new Set(names).size).toBe(names.length)
    expect(names.every((n) => n.length > 0 && n === n.trim())).toBe(true)
  })
})

describe('themePresets — colour values', () => {
  it('renders surface and text colours as solid 6-digit hex', () => {
    const offenders: string[] = []
    for (const preset of themePresets) {
      for (const field of HEX_FIELDS) {
        const value = preset[field]
        if (!HEX.test(value)) offenders.push(`${preset.id}.${field}=${value}`)
      }
    }
    expect(offenders).toEqual([])
  })

  it('renders glass layers as valid rgba() strings', () => {
    const offenders: string[] = []
    for (const preset of themePresets) {
      for (const field of RGBA_FIELDS) {
        const value = preset[field]
        if (!RGBA.test(value)) offenders.push(`${preset.id}.${field}=${value}`)
      }
    }
    expect(offenders).toEqual([])
  })

  it('restricts colorScheme to the two color-scheme values CSS understands', () => {
    const schemes = new Set(themePresets.map((p) => p.colorScheme))
    expect([...schemes].sort()).toEqual(['dark', 'light'])
  })
})

describe('themePresets — picker grouping contract', () => {
  it('declares no duplicate categories and includes the known families', () => {
    expect(new Set(themeCategories).size).toBe(themeCategories.length)
    expect(themeCategories).toContain('Editor')
    expect(themeCategories).toContain('Accessible')
  })

  it('lists every category that a preset actually uses', () => {
    const declared = new Set(themeCategories)
    const orphaned = themePresets
      .filter((p) => p.category !== undefined && !declared.has(p.category))
      .map((p) => `${p.id}:${p.category}`)
    expect(orphaned).toEqual([])
  })

  it('backs every declared category with at least one preset', () => {
    const used = new Set(themePresets.map((p) => p.category))
    const empty = themeCategories.filter((c) => !used.has(c))
    expect(empty).toEqual([])
  })
})

describe('themePresets — readability', () => {
  it('pairs each colorScheme with a matching background luminance', () => {
    const offenders: string[] = []
    for (const preset of themePresets) {
      const bg = luminance(preset.bg)
      if (preset.colorScheme === 'dark' && bg >= 0.5) offenders.push(`${preset.id} dark bg=${bg.toFixed(2)}`)
      if (preset.colorScheme === 'light' && bg <= 0.5) offenders.push(`${preset.id} light bg=${bg.toFixed(2)}`)
    }
    expect(offenders).toEqual([])
  })

  it('keeps primary text legible against its own background', () => {
    const offenders: string[] = []
    for (const preset of themePresets) {
      const delta = Math.abs(luminance(preset.bg) - luminance(preset.textPrimary))
      if (delta < 0.35) offenders.push(`${preset.id} contrast=${delta.toFixed(2)}`)
    }
    expect(offenders).toEqual([])
  })
})
